{"sql": "WITH o AS (
  SELECT order_id, order_status FROM orders
  WHERE order_purchase_timestamp >= '2017-01-01' AND order_purchase_timestamp < '2018-01-01'
), f AS (
  SELECT order_id, sum(freight_value) AS freight FROM order_items GROUP BY order_id
), j AS (
  SELECT o.order_id, o.order_status, f.freight FROM o JOIN f ON f.order_id=o.order_id
), q AS (
  SELECT *, ntile(10) OVER (ORDER BY freight) AS decile FROM j
)
SELECT decile, count(*) AS orders, round(min(freight),2) AS min_freight, round(max(freight),2) AS max_freight,
  count(*) FILTER (WHERE order_status='canceled') AS canceled,
  round(100.0*count(*) FILTER (WHERE order_status='canceled')/nullif(count(*),0),4) AS cancel_pct
FROM q GROUP BY decile ORDER BY decile"}

